        first.resize(700, 650);
        first.move(20, 20);
        first.show();
        first.activateWindow();
        QTest::qWait(50);

        auto* workspace =
            first.findChild<QSplitter*>(
                QStringLiteral("workspaceSplitter"));
        auto* editor =
            first.findChild<QSplitter*>(
                QStringLiteral("editorSplitter"));
        auto* results =
            first.findChild<QSplitter*>(
                QStringLiteral("resultsSplitter"));
