void GuiSmokeTests::rejectsInvalidActiveEditorBeforeSave()
{
    QTemporaryDir directory;
    QVERIFY(directory.isValid());
    const QString manifest = directory.filePath(QStringLiteral("project.regmap.yaml"));
    createTwoRegisterProject(manifest);

    MainWindow window;
    window.openProjectPath(manifest);
    window.resize(1100, 720);
    window.show();
    QTest::qWait(50);
    auto* registers = window.findChild<QTableView*>(QStringLiteral("registerView"));
    auto* hierarchy =
        window.findChild<QTreeView*>(
            QStringLiteral("hierarchyView"));
    auto* controller = window.findChild<ProjectController*>();
    auto* pageBase =
        window.findChild<QLineEdit*>(
            QStringLiteral("pageBaseEdit"));
    auto* pageWidth =
        window.findChild<QLineEdit*>(
            QStringLiteral("pageWidthEdit"));
    auto* blockBase =
        window.findChild<QLineEdit*>(
            QStringLiteral("blockBaseEdit"));
    auto* blockSize =
        window.findChild<QLineEdit*>(
            QStringLiteral("blockSizeEdit"));
    QVERIFY(registers != nullptr);
    QVERIFY(hierarchy != nullptr);
    QVERIFY(controller != nullptr);
    QVERIFY(pageBase != nullptr);
    QVERIFY(pageWidth != nullptr);
    QVERIFY(blockBase != nullptr);
    QVERIFY(blockSize != nullptr);
    QVERIFY(pageBase->toolTip().contains(
        QStringLiteral("0x-prefixed")));
    QVERIFY(pageWidth->toolTip().contains(
        QStringLiteral("1 to 64")));
    QVERIFY(blockBase->toolTip().contains(
        QStringLiteral("0x-prefixed")));
    QVERIFY(blockSize->toolTip().contains(
        QStringLiteral("clear to leave")));
    QVERIFY(!controller->isDirty());

    QSignalSpy syncSpy(controller, &ProjectController::syncStatusChanged);
    const QModelIndex width = registers->model()->index(0, 3);
    const QString editedRegisterId =
        width.data(Qt::UserRole + 1).toString();
    QVERIFY(!editedRegisterId.isEmpty());
    registers->setCurrentIndex(width);
    registers->scrollTo(width);
    registers->setFocus(Qt::OtherFocusReason);
    registers->edit(width);
    QCoreApplication::processEvents();
    const auto visibleEditor = [registers]() -> QLineEdit* {
        const auto editors = registers->findChildren<QLineEdit*>();
        const auto visible = std::ranges::find_if(
            editors, [](const QLineEdit* editor) { return editor->isVisible(); });
        return visible == editors.end() ? nullptr : *visible;
    };
    QTRY_VERIFY_WITH_TIMEOUT(visibleEditor() != nullptr, 2000);
    QLineEdit* invalidEditor = visibleEditor();
    invalidEditor->selectAll();
    QTest::keyClicks(invalidEditor, QStringLiteral("invalid-width"));
    QCOMPARE(invalidEditor->text(), QStringLiteral("invalid-width"));
    QCOMPARE(registers->model()->index(0, 3).data().toString(),
             QStringLiteral("32"));

    QSignalSpy resetSpy(registers->model(), &QAbstractItemModel::modelReset);
    QTest::keyClick(invalidEditor, Qt::Key_S, Qt::ControlModifier);
    QTRY_VERIFY_WITH_TIMEOUT(resetSpy.count() > 0, 2000);
    QTRY_COMPARE_WITH_TIMEOUT(registers->model()->index(0, 3).data().toString(),
                              QStringLiteral("32"), 2000);
    QTRY_COMPARE_WITH_TIMEOUT(
        registers->currentIndex()
            .data(Qt::UserRole + 1)
            .toString(),
        editedRegisterId,
        2000);
    QTRY_COMPARE_WITH_TIMEOUT(
        registers->currentIndex().column(),
        3,
        2000);
    QTRY_VERIFY_WITH_TIMEOUT(
        registers->hasFocus(),
        2000);
    QCOMPARE(syncSpy.count(), 0);
    QVERIFY(window.statusBar()->currentMessage().contains(
        QStringLiteral("Edit rejected: expected")));
    QVERIFY(!controller->isDirty());

    const QModelIndex blockIndex =
        hierarchyIndexByObjectId(
            hierarchy->model(),
            QStringLiteral("block-control"));
    QVERIFY(blockIndex.isValid());
    hierarchy->setCurrentIndex(QModelIndex{});
    QCoreApplication::processEvents();
    hierarchy->setCurrentIndex(blockIndex);
    QCoreApplication::processEvents();
    QVERIFY(!pageWidth->isReadOnly());
    pageWidth->setFocus(Qt::OtherFocusReason);
    pageWidth->selectAll();
    QTest::keyClicks(
        pageWidth,
        QStringLiteral("0"));
    QCOMPARE(pageWidth->text(), QStringLiteral("0"));
    QTest::keyClick(
        pageWidth,
        Qt::Key_S,
        Qt::ControlModifier);
    QTRY_COMPARE_WITH_TIMEOUT(
        pageWidth->text(),
        QStringLiteral("32"),
        2000);
    QTRY_VERIFY_WITH_TIMEOUT(
        pageWidth->hasFocus(),
        2000);
    QTRY_COMPARE_WITH_TIMEOUT(
        pageWidth->selectedText(),
        QStringLiteral("32"),
        2000);
    QCOMPARE(syncSpy.count(), 0);
    QVERIFY(window.statusBar()->currentMessage().contains(
        QStringLiteral("1 to 64")));
    QVERIFY(!controller->isDirty());
    makeGeneratedFilesWritable(directory.path());
}

void GuiSmokeTests::protectsActiveEditorDuringHierarchyNavigation()
{
    QTemporaryDir directory;
    QVERIFY(directory.isValid());
    const QString manifest =
        directory.filePath(
            QStringLiteral(
                "hierarchy-active-editor.regmap.yaml"));
    createTwoRegisterProject(manifest);

    MainWindow window;
    QVERIFY(
        window.openProjectPath(
            manifest));
    window.resize(1100, 720);
    window.show();
    window.activateWindow();
    QTest::qWait(50);

    auto* hierarchy =
        window.findChild<QTreeView*>(
            QStringLiteral(
                "hierarchyView"));
    auto* registers =
        window.findChild<QTableView*>(
            QStringLiteral(
                "registerView"));
    auto* controller =
        window.findChild<
            ProjectController*>();
    QVERIFY(hierarchy != nullptr);
    QVERIFY(registers != nullptr);
    QVERIFY(controller != nullptr);

    QVERIFY(
        controller->editWorkspace(
            QStringLiteral(
                "Add hierarchy navigation target"),
            [](regmap::Workspace&
                   workspace) {
                regmap::AddressSpace page;
                page.id =
                    "space-secondary";
                page.name =
                    "Secondary";
                page.baseAddress =
                    0x1000;
                page.addressWidth = 32;
                regmap::RegisterBlock
                    block;
                block.id =
                    "block-secondary";
                block.name =
                    "Secondary Block";
                block.baseAddress = 0;
                block.size = 0x100;
                page.blocks.push_back(
                    std::move(block));
                workspace.addressSpaces
                    .push_back(
                        std::move(page));
            }));

    QModelIndex currentBlock =
        hierarchyIndexByObjectId(
            hierarchy->model(),
            QStringLiteral(
                "block-control"));
    QModelIndex secondaryBlock =
        hierarchyIndexByObjectId(
            hierarchy->model(),
            QStringLiteral(
                "block-secondary"));
    QVERIFY(currentBlock.isValid());
    QVERIFY(secondaryBlock.isValid());
    hierarchy->setCurrentIndex(
        currentBlock);
    QCoreApplication::processEvents();

    int controlRow = -1;
    for (int row = 0;
         row <
         registers->model()
             ->rowCount();
         ++row) {
        if (registers->model()
                ->index(row, 0)
                .data(
                    Qt::UserRole + 1)
                .toString() ==
            QStringLiteral(
                "reg-control")) {
            controlRow = row;
            break;
        }
    }
    QVERIFY(controlRow >= 0);
    const QModelIndex width =
        registers->model()->index(
            controlRow, 3);
    registers->setCurrentIndex(width);
    registers->scrollTo(width);
    registers->setFocus(
        Qt::OtherFocusReason);
    registers->edit(width);
    const auto visibleEditor =
        [registers]() -> QLineEdit* {
        const auto editors =
            registers
                ->findChildren<QLineEdit*>();
        const auto visible =
            std::ranges::find_if(
                editors,
                [](const QLineEdit* editor) {
                    return editor->isVisible();
                });
        return visible ==
                editors.end()
            ? nullptr
            : *visible;
    };
    QTRY_VERIFY_WITH_TIMEOUT(
        visibleEditor() != nullptr,
        2000);
    visibleEditor()->selectAll();
    QTest::keyClicks(
        visibleEditor(),
        QStringLiteral(
            "invalid-width"));

    hierarchy->scrollTo(
        secondaryBlock);
    QTest::mouseClick(
        hierarchy->viewport(),
        Qt::LeftButton,
        Qt::NoModifier,
        hierarchy
            ->visualRect(
                secondaryBlock)
            .center());
    QTest::qWait(
        QApplication::
                doubleClickInterval() +
            100);
    QTRY_COMPARE_WITH_TIMEOUT(
        hierarchy->currentIndex()
            .data(Qt::UserRole + 1)
            .toString(),
        QStringLiteral(
            "block-control"),
        2000);
    QTRY_COMPARE_WITH_TIMEOUT(
        registers->currentIndex()
            .data(Qt::UserRole + 1)
            .toString(),
        QStringLiteral(
            "reg-control"),
        2000);
    QTRY_COMPARE_WITH_TIMEOUT(
        registers->currentIndex()
            .column(),
        3,
        2000);
    QTRY_COMPARE_WITH_TIMEOUT(
        registers->currentIndex()
            .data()
            .toString(),
        QStringLiteral("32"),
        2000);
    QTRY_VERIFY_WITH_TIMEOUT(
        registers->hasFocus(),
        2000);
    QVERIFY(
        window.statusBar()
            ->currentMessage()
            .contains(
                QStringLiteral(
                    "Edit rejected")));

    secondaryBlock =
        hierarchyIndexByObjectId(
            hierarchy->model(),
            QStringLiteral(
                "block-secondary"));
    QVERIFY(secondaryBlock.isValid());
    hierarchy->scrollTo(
        secondaryBlock);
    QTest::mouseClick(
        hierarchy->viewport(),
        Qt::LeftButton,
        Qt::NoModifier,
        hierarchy
            ->visualRect(
                secondaryBlock)
            .center());
    QTRY_COMPARE_WITH_TIMEOUT(
        hierarchy->currentIndex()
            .data(Qt::UserRole + 1)
            .toString(),
        QStringLiteral(
            "block-secondary"),
        2000);

    makeGeneratedFilesWritable(
        directory.path());
}

